#[derive(Clone,Copy)]pub enum MessagePiece<'a>{Literal(&'static str),Original(RetainedCloneRef<'a,String>),EscapedOriginal(RetainedCloneRef<'a,String>),Unsigned(usize)}
pub trait DynamicMessageSource{
 fn mutation(&self)->RetainedCloneRef<'_,LayoutMutation>;
 fn baseline(&self)->RetainedCloneRef<'_,LayoutSnapshot>;
 fn identity(&self)->usize;
 fn level(&self)->Severity;
 fn code(&self)->&'static str;
 fn piece_count(&self)->usize;
 fn piece(&self,index:usize)->MessagePiece<'_>;
 fn target_count(&self)->usize;
 fn target(&self,index:usize)->RetainedCloneRef<'_,String>;
}
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"dynamic diagnostic original source custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<DynamicMessagePreparation>()*2+512,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=fixed().copy_bytes;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed().copy_bytes,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=fixed().copy_bytes;p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn digits(value:usize,out:&mut[u8;20])->usize{let mut value=value;let mut start=20;loop{start-=1;out[start]=b'0'+(value%10)as u8;value/=10;if value==0{return start}}}
fn piece_len(piece:MessagePiece<'_>)->usize{match piece{MessagePiece::Literal(s)=>s.len(),MessagePiece::Original(s)=>s.get().len(),MessagePiece::EscapedOriginal(_)=>0,MessagePiece::Unsigned(value)=>{let mut out=[0;20];20-digits(value,&mut out)}}}
/// 🧳 Every partial final String, original target field, alias and original ledger stays closeable.
pub struct DynamicMessagePreparation{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,piece_binding:Option<RetainedCloneBinding>,identity:usize,level:Severity,code_source:Option<&'static str>,pieces:usize,target_count:usize,extent:usize,index:usize,offset:usize,phase:u8,literal:Option<&'static str>,number:usize,digits:[u8;20],digit_start:usize,piece_kind:u8,text:ManuallyDrop<Option<String>>,code:ManuallyDrop<Option<String>>,targets:ManuallyDrop<Option<Vec<String>>>,field:RetainedFieldPreparation<String>,rows:ManuallyDrop<Option<Vec<MutationMessage>>>,ledger:ManuallyDrop<Option<MutationMessageLedgerRetirement>>,retirement:RetainedCloneClose,transferred:bool,closing:bool}
impl Default for DynamicMessagePreparation{fn default()->Self{Self{m:None,b:None,piece_binding:None,identity:0,level:Severity::Warning,code_source:None,pieces:0,target_count:0,extent:0,index:0,offset:0,phase:0,literal:None,number:0,digits:[0;20],digit_start:20,piece_kind:0,text:ManuallyDrop::new(None),code:ManuallyDrop::new(None),targets:ManuallyDrop::new(None),field:Default::default(),rows:ManuallyDrop::new(None),ledger:ManuallyDrop::new(None),retirement:Default::default(),transferred:false,closing:false}}}
impl DynamicMessagePreparation{
 pub fn ready(&self)->bool{self.phase==16&&!self.closing&&!self.transferred}
 fn verify(&self,s:&impl DynamicMessageSource)->Result<(),ValueError>{s.mutation().check_binding(&self.m)?;s.baseline().check_binding(&self.b)?;if self.closing||self.transferred{return Err(fault())}if self.phase>=3&&(self.identity!=s.identity()||self.level!=s.level()||self.pieces!=s.piece_count()||self.target_count!=s.target_count()||!self.code_source.is_some_and(|code|std::ptr::eq(code,s.code()))){return Err(fault())}Ok(())}
 fn piece_text<'a>(&'a self,s:&'a impl DynamicMessageSource)->Result<&'a str,ValueError>{match(self.piece_kind,s.piece(self.index)){(0,MessagePiece::Literal(value))if self.literal.is_some_and(|old|std::ptr::eq(old,value))=>Ok(value),(1,MessagePiece::Original(value))|(3,MessagePiece::EscapedOriginal(value))=>{value.check_binding(&self.piece_binding)?;Ok(value.get().as_str())},(2,MessagePiece::Unsigned(value))if self.number==value=>std::str::from_utf8(&self.digits[self.digit_start..]).map_err(|_|fault()),_=>Err(fault())}}
 pub fn demand(&self,s:&impl DynamicMessageSource,body:usize)->Result<RetirementDemand,ValueError>{self.verify(s)?;Ok(match self.phase{0=>nested(s.mutation().binding_demand(&self.m)?.unwrap_or_default()),1=>nested(s.baseline().binding_demand(&self.b)?.unwrap_or_default()),2=>fixed(),3=>RetirementDemand{copy_bytes:fixed().copy_bytes+20,..fixed()},4=>RetirementDemand{capacity_bytes:self.extent,..fixed()},5=>if self.index==self.pieces{fixed()}else if let MessagePiece::Original(source)|MessagePiece::EscapedOriginal(source)=s.piece(self.index){nested(source.binding_demand(&self.piece_binding)?.unwrap_or_default())}else{fixed()},6=>{let value=self.piece_text(s)?;if self.piece_kind==3{return Ok(RetirementDemand{copy_bytes:fixed().copy_bytes+20,..fixed()})}let mut end=value.len().min(self.offset+256);while end>self.offset&&!value.is_char_boundary(end){end-=1}let mut d=fixed();d.copy_bytes+=end-self.offset;d},7=>nested(RetainedCloneBinding::close_demand(&self.piece_binding,body.min(256))?),8=>RetirementDemand{capacity_bytes:self.target_count.checked_mul(size_of::<String>()).ok_or_else(fault)?,..fixed()},9=>if self.index==self.target_count{fixed()}else if self.field.value().is_some(){let mut d=nested(self.field.exchange_demand()?);d.copy_bytes+=size_of::<String>()*2;d}else{nested(self.field.demand(s.target(self.index),body.min(256))?)},10=>nested(self.field.close_demand(body.min(256))?),11=>fixed(),12=>{let code=self.code_source.ok_or_else(fault)?;RetirementDemand{copy_bytes:fixed().copy_bytes+code.len(),capacity_bytes:code.len(),..fixed()}},13=>RetirementDemand{capacity_bytes:size_of::<MutationMessage>(),..fixed()},14..=16=>fixed(),_=>return Err(fault())})}
 pub fn advance(&mut self,s:&impl DynamicMessageSource,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(s,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{
 0=>{p=receipt(s.mutation().bind(&mut self.m,child(g)).map_err(refused)?.unwrap_or_default());self.phase=1},1=>{p=receipt(s.baseline().bind(&mut self.b,child(g)).map_err(refused)?.unwrap_or_default());self.phase=2},
 2=>{if s.code().len()>256{return Err(fault().with_retained_progress(p))}self.identity=s.identity();self.level=s.level();self.code_source=Some(s.code());self.pieces=s.piece_count();self.target_count=s.target_count();self.phase=3},
 3=>if self.index==self.pieces{self.index=0;self.offset=0;self.phase=4}else if let MessagePiece::EscapedOriginal(source)=s.piece(self.index){let value=source.get();if self.offset==value.len(){self.offset=0;self.index+=1}else{let scalar=value[self.offset..].chars().next().ok_or_else(fault)?;let mut bytes=[0;10];let length=debug::rust_string_debug_scalar(scalar,&mut bytes);self.extent=self.extent.checked_add(length).ok_or_else(fault)?;self.offset+=scalar.len_utf8()}}else{self.extent=self.extent.checked_add(piece_len(s.piece(self.index))).ok_or_else(fault)?;self.index+=1},
 4=>{self.phase=254;*self.text=Some(String::new());let text=self.text.as_mut().unwrap();let reserved=text.try_reserve_exact(self.extent);p.retained_capacity_bytes=text.capacity();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=5},
 5=>if self.index==self.pieces{self.index=0;self.phase=8}else{match s.piece(self.index){MessagePiece::Literal(value)=>{self.literal=Some(value);self.piece_kind=0},MessagePiece::Original(source)=>{p=receipt(source.bind(&mut self.piece_binding,child(g)).map_err(refused)?.unwrap_or_default());self.piece_kind=1},MessagePiece::EscapedOriginal(source)=>{p=receipt(source.bind(&mut self.piece_binding,child(g)).map_err(refused)?.unwrap_or_default());self.piece_kind=3},MessagePiece::Unsigned(value)=>{self.number=value;self.digit_start=digits(value,&mut self.digits);self.piece_kind=2}}self.offset=0;self.phase=6},
 6=>{let value=match(self.piece_kind,s.piece(self.index)){(0,MessagePiece::Literal(value))if self.literal.is_some_and(|old|std::ptr::eq(old,value))=>value,(1,MessagePiece::Original(value))|(3,MessagePiece::EscapedOriginal(value))=>{value.check_binding(&self.piece_binding)?;value.get().as_str()},(2,MessagePiece::Unsigned(value))if self.number==value=>std::str::from_utf8(&self.digits[self.digit_start..]).map_err(|_|fault())?,_=>return Err(fault())};let start=self.offset;if self.piece_kind==3{if start==value.len(){self.phase=7}else{let scalar=value[start..].chars().next().ok_or_else(fault)?;let mut bytes=[0;10];let count=debug::rust_string_debug_scalar(scalar,&mut bytes);let fragment=std::str::from_utf8(&bytes[..count]).map_err(|_|fault())?;let text=self.text.as_mut().ok_or_else(fault)?;if text.len().checked_add(count).is_none_or(|length|length>self.extent){return Err(fault().with_retained_progress(p))}text.push_str(fragment);self.offset+=scalar.len_utf8();if self.offset==value.len(){self.phase=7}}return Ok(RetainedCloneStep::Progress(p))}let mut end=value.len().min(start+256);while end>start&&!value.is_char_boundary(end){end-=1}let bytes=end-start;if self.text.as_ref().ok_or_else(fault)?.len().checked_add(bytes).is_none_or(|length|length>self.extent){return Err(fault().with_retained_progress(p))}let complete=end==value.len();self.text.as_mut().ok_or_else(fault)?.push_str(&value[start..end]);self.offset=end;if complete{self.phase=7}},
 7=>{p=receipt(RetainedCloneBinding::close_one(&mut self.piece_binding,child(g)).map_err(refused)?.progress());if self.piece_binding.is_none(){self.literal=None;self.index+=1;self.offset=0;self.phase=5}},
 8=>{self.phase=254;*self.targets=Some(Vec::new());let rows=self.targets.as_mut().unwrap();let reserved=rows.try_reserve_exact(self.target_count);p.retained_capacity_bytes=rows.capacity()*size_of::<String>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=9},
 9=>if self.index==self.target_count{self.phase=12}else if self.field.value().is_some(){let(value,paid)=self.field.take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed().copy_bytes-size_of::<String>()*2,maximum_depth:g.maximum_depth-1,..g}).map_err(refused)?;p=receipt(paid);p.copied_bytes+=size_of::<String>()*2;self.targets.as_mut().ok_or_else(fault)?.push(value.ok_or_else(fault)?);self.field.begin_close();self.phase=10}else{p=receipt(self.field.advance(s.target(self.index),body.min(256),child(g)).map_err(refused)?.progress())},
 10=>{p=receipt(self.field.close_step(child(g)).map_err(refused)?.progress());if self.field.terminal_is_empty(){self.phase=11}},11=>{self.field=Default::default();self.index+=1;self.phase=9},
 12=>{let code=self.code_source.ok_or_else(fault)?;self.phase=254;*self.code=Some(String::new());let target=self.code.as_mut().unwrap();let reserved=target.try_reserve_exact(code.len());p.retained_capacity_bytes=target.capacity();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}target.push_str(code);self.phase=13},
 13=>{self.phase=254;*self.rows=Some(Vec::new());let rows=self.rows.as_mut().unwrap();let reserved=rows.try_reserve_exact(1);p.retained_capacity_bytes=rows.capacity()*size_of::<MutationMessage>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=14},
 14=>{self.rows.as_mut().ok_or_else(fault)?.push(MutationMessage{level:self.level,code:FaultCode(self.code.take().ok_or_else(fault)?),message:self.text.take().ok_or_else(fault)?,target:self.targets.take().ok_or_else(fault)?,op_index:None});self.phase=15},
 15=>{*self.ledger=Some(MutationMessageLedgerRetirement::new(String::new(),self.rows.take().ok_or_else(fault)?));self.phase=16},16=>{},_=>return Err(fault())}Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->RetirementDemand{nested(RetirementDemand{copy_bytes:size_of::<Vec<MutationMessage>>(),depth:1,..Default::default()})}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(Vec<MutationMessage>,RetainedCloneProgress)>,ValueError>{if !self.ready(){return Err(fault())}if !retained_clone_grant_admits(g,self.take_demand()){return Ok(None)}let result=self.ledger.as_mut().ok_or_else(fault)?.take_messages_controlled(child(g)).map_err(refused)?;if let Some((rows,p))=result{self.transferred=true;Ok(Some((rows,receipt(p))))}else{Ok(None)}}
 pub fn begin_close(&mut self){self.closing=true;self.field.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault())}if !self.field.terminal_is_empty(){return Ok(nested(self.field.close_demand(body.min(256))?))}if self.piece_binding.is_some(){return Ok(nested(RetainedCloneBinding::close_demand(&self.piece_binding,body.min(256))?))}if !self.retirement.is_empty(){return Ok(nested(self.retirement.next_owner_demands::<String>(false,&None,body.min(256))?))}if self.text.is_some()||self.code.is_some(){return Ok(nested(self.retirement.next_owner_demands::<String>(true,&None,body.min(256))?))}if self.targets.is_some(){return Ok(nested(self.retirement.next_owner_demands::<Vec<String>>(true,&None,body.min(256))?))}if self.rows.is_some(){return Ok(fixed())}if let Some(ledger)=self.ledger.as_ref(){return Ok(nested(RetirementDemand{copy_bytes:ledger.next_copy_byte_demand(),capacity_bytes:ledger.next_capacity_byte_demand(body.min(256))?,release_bytes:ledger.next_release_byte_demand()?,depth:ledger.next_depth_demand()?}))}if self.b.is_some()||self.m.is_some(){return Ok(nested(RetainedCloneBinding::close_demand(if self.b.is_some(){&self.b}else{&self.m},body.min(256))?))}Ok(fixed())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.field.terminal_is_empty(){return self.field.close_step(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}if self.piece_binding.is_some(){return RetainedCloneBinding::close_one(&mut self.piece_binding,child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}if !self.retirement.is_empty(){return self.retirement.step_granted(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}if let Some(step)=self.retirement.begin_granted(&mut self.text,child(g)).map_err(refused)?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())))}if let Some(step)=self.retirement.begin_granted(&mut self.code,child(g)).map_err(refused)?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())))}if let Some(step)=self.retirement.begin_granted(&mut self.targets,child(g)).map_err(refused)?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())))}if let Some(rows)=self.rows.take(){*self.ledger=Some(MutationMessageLedgerRetirement::new(String::new(),rows));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if let Some(ledger)=self.ledger.as_mut(){if !ledger.terminal_is_empty(){return ledger.close_step(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}*self.ledger=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if self.b.is_some()||self.m.is_some(){return RetainedCloneBinding::close_one(if self.b.is_some(){&mut self.b}else{&mut self.m},child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}self.literal=None;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.m.is_none()&&self.b.is_none()&&self.piece_binding.is_none()&&self.field.terminal_is_empty()&&self.text.is_none()&&self.code.is_none()&&self.targets.is_none()&&self.rows.is_none()&&self.ledger.is_none()&&self.retirement.is_empty()}
}
impl Drop for DynamicMessagePreparation{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"dynamic diagnostic requires exact original controlled closure")}}

